// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {Reentrance} from "../src/Reentrance.sol";

contract InvMutTest is Test {
    Reentrance c;
    function setUp() public { c = new Reentrance(); }

    function testFuzz_property(address actor, uint256 amountA, uint256 amountB) public {
        vm.assume(actor != address(0));
        amountA = bound(amountA, 1, 1 ether);
        amountB = bound(amountB, 1, 1 ether);

        vm.deal(actor, amountA + amountB);
        vm.prank(actor);
        c.addToBalance{value: amountA}();
        vm.prank(actor);
        c.addToBalance{value: amountB}();

        assertTrue(c.getBalance(actor) == amountA + amountB, "deposits must accumulate");
    }
}
